export function updateStatusUserStory(userStoryId: any, status: any) {
  let body = {};
  switch (status) {
    case "PENDING":
      body = {
        status: "PLANNED",
      };
      break;
    case "PLANNED":
      body = {
        status: "DEVELOPMENT",
      };
      break;
    case "EDIT":
      body = {
        status: "HAS BEEN EDITED",
      };
      break;
    case "HAS BEEN EDITED":
      body = {
        status: "VALIDATED",
      };
      break;
    case "DEVELOPMENT":
      body = {
        status: "TESTING",
      };
      break;
    case "TESTING":
      body = {
        status: "VALIDATED",
      };
      break;
    default:
      break;
  }
  return {
    type: USER_STORY_UPDATE_STATUS,
    payload: {
      url: `mis/user_stories/${userStoryId}/status`,
      body,
    },
  };
}

