function VerticalField(props: IVerticalFieldProps) {
  const { children } = props;
  return <Form.Group className="mb-2">{children}</Form.Group>;
}

function HorizontalField(props: IHorizontalFieldProps) {
  const { children } = props;
  return (
    <Form.Group as={Row} className="mb-3">
      {children}
    </Form.Group>
  );
}

export const renderFormError = (touched: any, error: any) => {
  if (touched && error) {
    return (
      <Form.Control.Feedback type="invalid">{error}</Form.Control.Feedback>
    );
  }
  return null;
};

export const renderLabel = (
  label: any,
  inputName: any,
  required: any,
  vertical?: any,
  labelTooltip?: string,
  labelClassName?: string
) => (
  <Form.Label
    htmlFor={inputName}
    column={!vertical}
    sm={2}
    className={`fw-bold col-form-label custom_label ${labelClassName}`}
  >
    <div>
      {required && <span style={{ color: "#ed5565" }}>*&nbsp;</span>}
      {label}
    </div>
    <div>
      {labelTooltip && (
        <Tooltip
          title={
            <span className="tooltip-multiline">
              {Translator.trans(labelTooltip)}
            </span>
          }
          placement="top"
          arrow
        >
          <IconButton>
            <HelpOutlineIcon />
          </IconButton>
        </Tooltip>
      )}
    </div>
  </Form.Label>
);

const renderInlineSelect = ({
  input,
  required,
  meta: { touched, error },
  children,
  ...custom
}: IInlineSelectProps) => (
  <>
    <Form.Select
      {...input}
      {...custom}
      required={required}
      isValid={touched && !error}
      isInvalid={touched && error}
    >
      {children}
    </Form.Select>
    {renderFormError(touched, error)}
  </>
);
export { renderInlineSelect };

const renderSelect = ({
  input,
  label,
  required,
  meta: { touched, error },
  children,
  ...custom
}: ISelectProps) => (
  <HorizontalField>
    {label ? renderLabel(label, input.name, required) : ""}
    <Col sm={10}>
      {renderInlineSelect({
        input,
        label,
        required,
        meta: { touched, error },
        children,
        ...custom,
      })}
    </Col>
  </HorizontalField>
);
export { renderSelect };

const renderVerticalSelect = ({
  input,
  label,
  required,
  meta: { touched, error },
  children,
  ...custom
}: IVerticalSelectProps) => (
  <VerticalField>
    {label ? renderLabel(label, input.name, required, true) : ""}
    {renderInlineSelect({
      input,
      label,
      required,
      meta: { touched, error },
      children,
      ...custom,
    })}
  </VerticalField>
);
export { renderVerticalSelect };

const renderTextarea = ({ input, meta, label, ...custom }: ITextareaProps) => (
  <HorizontalField>
    {renderLabel(label, input.name, custom.required)}
    <Col sm={10}>
      <Form.Control {...input} as="textarea" rows="4" {...custom} />
      {renderFormError(meta.touched, meta.error)}
    </Col>
  </HorizontalField>
);
export { renderTextarea };

const renderInlineTextarea = ({
  input,
  meta,
  parentClassName,
  hideLabel,
  subLabel,
  labelTooltip,
  ...custom
}: IInlineTextareaProps) => (
  <VerticalField>
    <div className={`${parentClassName || ""}`}>
      {!hideLabel && (
        <label
          className={`col-form-label ${
            subLabel && "text_area__label_wrapper"
          } custom_label`}
          htmlFor={input.name}
        >
          <div>
            {custom.required && (
              <span style={{ color: "#ed5565" }}>*&nbsp;</span>
            )}
            {custom.label}
          </div>
          <div>
            {labelTooltip && (
              <Tooltip
                title={Translator.trans(labelTooltip)}
                placement="top"
                arrow
              >
                <IconButton>
                  <HelpOutlineIcon />
                </IconButton>
              </Tooltip>
            )}
          </div>
        </label>
      )}
      {subLabel && (
        <Typography className="text_area__sub_label" variant="caption">
          {subLabel}
        </Typography>
      )}
      <Form.Control
        {...input}
        {...custom}
        rows={`${custom.rows ?? "4"}`}
        as="textarea"
        isValid={meta.touched && !meta.error}
        isInvalid={meta.touched && meta.error}
      />
    </div>
    {renderFormError(meta.touched, meta.error)}
  </VerticalField>
);
export { renderInlineTextarea };

function RenderInlineFileInput({
  input,
  label,
  required,
  meta,
  showError,
  accept,
  labelTooltip,
  multiple,
}: IInlineFileInputProps) {
  const ref = useRef<any>();

  useEffect(() => {
    if (!input.value && ref.current) {
      ref.current.value = null;
    }
  }, [input.value]);

  return (
    <VerticalField>
      {renderLabel(label, input.name, required, true, labelTooltip)}
      <Form.Control
        name={input.name}
        onChange={input.onChange}
        type="file"
        onBlur={showError ? () => input.onBlur(input.value) : undefined}
        accept={accept}
        multiple={multiple}
        ref={ref}
      />
      {renderFormError(meta.touched, meta.error)}
    </VerticalField>
  );
}
export { RenderInlineFileInput as renderInlineFileInput };

const renderInput = ({
  input,
  label,
  type,
  required,
  meta: { touched, error },
  children,
  ...custom
}: IInputProps) => {
  const childrenInput = children || (
    <Form.Control
      {...input}
      {...custom}
      type={type}
      required={required}
      size="lg"
      isInvalid={touched && error}
      isValid={touched && !error}
    />
  );

  return (
    <HorizontalField>
      {renderLabel(label, input.name, required)}
      <Col sm={10}>
        {custom.addon ? (
          <InputGroup className="mb-3" style={{ zIndex: 0 }}>
            {childrenInput}
            <InputGroup.Text>{custom.addon}</InputGroup.Text>
          </InputGroup>
        ) : (
          childrenInput
        )}
        {renderFormError(touched, error)}
      </Col>
    </HorizontalField>
  );
};
export { renderInput };

const renderVerticalInput = ({
  input,
  label,
  type,
  required,
  meta: { touched, error },
  children,
  allowNumbersOnly,
  allowFloatsOnly,
  labelTooltip,
  maxCharacters,
  labelClassName,
  ...custom
}: IVerticalInputProps) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let newValue = e.target.value;
    if (allowNumbersOnly) {
      newValue = extractDigits(e.target.value);
    }
    if (allowFloatsOnly) {
      newValue = extractFloat(e.target.value);
    }
    if (maxCharacters) {
      newValue = newValue.slice(0, maxCharacters);
    }
    input.onChange(newValue);
    if (custom.onChange) {
      custom.onChange(e, newValue);
    }
  };

  const childrenInput = children || (
    <Form.Control
      {...input}
      {...custom}
      type={type}
      required={`${required ? "required" : ""}`}
      isInvalid={touched && error}
      isValid={touched && !error}
      onChange={handleChange}
    />
  );

  return (
    <VerticalField>
      {renderLabel(
        label,
        input.name,
        required,
        true,
        labelTooltip,
        labelClassName
      )}
      {custom.addon ? (
        <InputGroup className="mb-3" style={{ zIndex: 0 }}>
          {childrenInput}
          <InputGroup.Text>{custom.addon}</InputGroup.Text>
        </InputGroup>
      ) : (
        childrenInput
      )}
      {renderFormError(touched, error)}
    </VerticalField>
  );
};
export { renderVerticalInput };

const renderInlineInput = ({
  input,
  meta,
  markUserChange,
  customError,
  size,
  labelClassName,
  ...custom
}: IInlineInputProps) => {
  const style: any = {};
  if (
    markUserChange &&
    meta.touched &&
    !meta.autofilled &&
    Number(meta.initial) !== Number(input.value) &&
    !meta.submitting
  ) {
    style.border = "2px solid #f8ac59";
    style.color = "#f8ac59";
    style.fontWeight = "bold";
  }

  const inputChildren = (
    <>
      {custom.label && (
        <Form.Label htmlFor={input.name} className={labelClassName}>
          {custom.label}
        </Form.Label>
      )}
      <Form.Control style={style} {...input} {...custom} size={size || "lg"} />
    </>
  );

  if (custom.addon) {
    return (
      <InputGroup size="sm">
        {inputChildren}
        {custom.addon && <InputGroup.Text>{custom.addon}</InputGroup.Text>}
        {renderFormError(customError, customError)}
      </InputGroup>
    );
  }
  return (
    <>
      {inputChildren}
      {renderFormError(customError, customError)}
    </>
  );
};
export { renderInlineInput };

