  required: any;
  name: any;
  placeholder: any;
  onChange: any;
  async: any;
  discriminator: any;
  extranetUsers?: any;
  isMulti?: boolean;
}

function ExtranetUserAsyncSelect({
  getExtranetUsers,
  extranetUsersListIsLoading,
  fetchExtranetUsersList,
  onChange,
  discriminator,
  async = true,
  required = false,
  label = "eContact",
  name = "contact",
  placeholder = "Search a Contact",
  isMulti,
  ...props
}: IProps) {
