    input.onChange(newValue);
  };

  return (
    <div>
      <Rating
        value={value}
        onChange={handleChange}
        className="rating_stars__custom_rating"
        {...rest}
      />

      {meta.touched && meta.error && (
        <span style={{ color: "red", fontSize: 12 }}>{meta.error}</span>
      )}
    </div>
  );
}

import React from "react";
import { connect } from "react-redux";
import { fetchROLE as fetchRoleAction } from "../../actions/role/roleActions";
import { getRoleMapping } from "../../selectors/role/roleSelector";
import { AppDispatch, RootState } from "../../store";
import GenericFormComponent from "../GenericFormComponent/GenericFormComponent";

interface IProps {
  roleList: any;
  roleListIsLoading: any;
  fetchROLE: any;
  label: any;
  required: any;
  name: any;
  placeholder?: any;
  onChange?: any;
  isMulti?: any;
}

function RoleSelect(props: IProps) {
  const {
    roleList,
    roleListIsLoading,
    fetchROLE,
    onChange,
    isMulti,
    required = false,
    label = "group",
    name = "group",
    placeholder = "Type to search a ROLE",
  } = props;
  return (
    <GenericFormComponent
      type={
        isMulti ? "MutliSelectStaticDropdown" : "SingleSelectStaticDropdown"
      }
      name={name}
      label={label}
      required={required}
      list={roleList}
      placeholder={placeholder}
      onChange={onChange}
      isLoadingExternally={roleListIsLoading}
      onInputChange={(input: any) => {
        if (!input || input.length < 3) {
          return;
        }
        fetchROLE(input);
      }}
    />
  );
}

const mapStateToProps = (state: RootState) => {
  const { role } = state;
  return {
    roleList: getRoleMapping(state),
    roleListIsLoading: role.roleListIsLoading,
  };
};

const mapDispatchToProps = (dispatch: AppDispatch) => {
  return {
    fetchROLE: (search: any) => {
      dispatch(fetchRoleAction(search));
    },
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(RoleSelect);

import React from "react";
import { connect } from "react-redux";
import { Field } from "redux-form";
import { getDeliveryAddressesMapping } from "../../../selectors/sparePartsRequest/deliveryAddressesSelector";
import { RootState } from "../../../store";

interface IProps {
  getDeliveryAddresses: any;
  label?: any;
  name?: any;
  discriminator?: any;
}

function DeliveryAddressesSelect({
  getDeliveryAddresses,
  name = "deliveryAddress",
  label = "Delivery Address",
  discriminator = "discr",
}: IProps) {
  const deliveryAddresses = getDeliveryAddresses(discriminator)
    .slice()
    .sort((a: any, b: any) => {
      const dateA = a.lastUsedAt ? new Date(a.lastUsedAt).getTime() : 0;
      const dateB = b.lastUsedAt ? new Date(b.lastUsedAt).getTime() : 0;
      return dateB - dateA;
    });
  return (
    <div className="form-control">
      {deliveryAddresses.length > 0 && (
        <div>
          <label className="col-form-label">{label}</label>
          <div>
            {deliveryAddresses.map((deliveryAddress: any, i: number) => (
              <div className="thumbnail" key={i}>
                <div className="radio radio-primary">
                  <Field
                    component="input"
                    name={name}
                    id={name + i}
                    type="radio"
                    value={deliveryAddress.value}
                  />
                  <label htmlFor={name + i}>
                    <p>
                      <a
                        href={`/en/private/sales/contacts/${deliveryAddress.contact.id}/show`}
                      >
                        {deliveryAddress.contact.lastname},{" "}
                        {deliveryAddress.contact.firstname} (ID#
                        {deliveryAddress.contact.id})
                      </a>
                      , {deliveryAddress.label}
                      {". "}
                      {deliveryAddress.firstname} {deliveryAddress.lastname}{" "}
                      {deliveryAddress.phone}{" "}
                      {deliveryAddress.lastUsedAt && (
                        <i>
                          Last used:{" "}
                          {new Date(
                            deliveryAddress.lastUsedAt
                          ).toLocaleDateString()}
                        </i>
                      )}
                    </p>
                  </label>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

const mapStateToProps = (state: RootState) => {
  return {
    getDeliveryAddresses: (discriminator: any) =>
      getDeliveryAddressesMapping(state, discriminator),
  };
};

export default connect(mapStateToProps)(DeliveryAddressesSelect);

import React from "react";
import { InjectedFormProps, reduxForm } from "redux-form";
import { connect } from "react-redux";
import AirportSelect from "./AirportSelect";
import DMSSelect from "./DMSSelect";
import CustomersSelect from "./CustomersSelect";
import PeopleAsyncSelect from "./PeopleAsyncSelect";
import CompetitorAsyncSelect from "./CompetitorAsyncSelect";
import MarketIntelligenceAsyncSelect from "./MarketIntelligenceAsyncSelect";
import CountriesSelect from "./CountriesSelect";
import ProductSelect from "./ProductSelect";
import EquipmentRecordAsyncSelect from "./EquipmentRecordAsyncSelect";
import { renderReactSelect, renderReactVerticalSelect } from "./Elements";
import ProductFamilyAsyncSelect from "./ProductFamilyAsyncSelect";
import ExtranetUserAsyncSelect from "./ExtranetUserAsyncSelect";
import BusinessPartnersSelect from "./BusinessPartnersSelect";
import NonConformityAsyncSelect from "./NonConformityAsyncSelect";
import PartItemMonologisticSelect from "./PartItemMonologisticSelect";
import { RootState } from "../../store";

type IFormData = any;

interface IProps {
  initialValue: any;
  componentAlias: any;
  name: any;
  inline: any;
  required: any;
  [key: string]: any;
}

interface IMappedProps {
  initialValueLabel: any;
}

interface IState {
  selectedValue: any;
}

type IWrappedProps = IProps & InjectedFormProps<IFormData, IProps>;

const selects: any = {
  airport: AirportSelect,
  dms: DMSSelect,
  customer: CustomersSelect,
  people: PeopleAsyncSelect,
  competitor: CompetitorAsyncSelect,
  marketIntelligence: MarketIntelligenceAsyncSelect,
  country: CountriesSelect,
  product: ProductSelect,
  equipmentRecord: EquipmentRecordAsyncSelect,
  productFamily: ProductFamilyAsyncSelect,
  extranetUser: ExtranetUserAsyncSelect,
  nonConformity: NonConformityAsyncSelect,
  businessPartner: BusinessPartnersSelect,
  item: PartItemMonologisticSelect,
};

class SymfonySelect extends React.Component<IWrappedProps, IState> {
  private hiddenInputRef = React.createRef<HTMLInputElement>();

  constructor(props: IWrappedProps, context: any) {
    super(props, context);
    this.state = {
      selectedValue: props.initialValue,
    };
  }

  render() {
    const { componentAlias, name, inline, required } = this.props;
    const { selectedValue } = this.state;
    const Component = selects[componentAlias];
    return (
      <div>
        <input
          type="hidden"
          value={selectedValue}
          name={name}
          ref={this.hiddenInputRef}
        />
        <Component
          // disabled={this.props.disabled}
          onChange={(selectedOption: any) => {
            this.setState({ selectedValue: selectedOption.value }, () => {
              this.hiddenInputRef.current?.dispatchEvent(
                new Event("change", { bubbles: true })
              );
            });
          }}
          component={inline ? renderReactSelect : renderReactVerticalSelect}
          {...this.props}
          name={name ?? `${componentAlias}-select`}
          required={required}
        />
      </div>
    );
  }
}

const formConfiguration = {
  enableReinitialize: true,
};

const mapStateToProps = (state: RootState, props: IProps & IMappedProps) => {
  let values = {};
  if (props.initialValueLabel) {
    values = {
      placeholder: props.initialValueLabel,
    };
  }
  return {
    ...values,
    form: `${props.componentAlias}-${props.name}`,
    initialValues: {
      [`${props.componentAlias}-select`]: {
        value: props.initialValue,
        label: props.initialValueLabel,
      },
    },
  };
};

export default connect(mapStateToProps)(
  reduxForm<IFormData, IProps>(formConfiguration)(SymfonySelect)
);

