import React from "react";
import { connect } from "react-redux";
import Translator from "bazinga-translator";
import {
  createSubscription as createSubscriptionAction,
  getSubscriptions,
} from "../../actions/common/subscriptionsActions";
import { troubleTicketAdditionalOwnerFactory } from "../../model/form/mis/factory";
import { MIS_UPDATE_TROUBLE_TICKET_OWNERS } from "../../constants";
import { getUserDetails } from "../../selectors/user/userSelectors";
import { updateTroubleTicket as updateTroubleTicketAction } from "../../actions/mis/troubleTicketsActions";
import { AppDispatch, RootState } from "../../store";

interface IProps {
  fetchSubscriptions: any;
  troubleTicket: any;
  updateTroubleTicket: any;
  connectedUser: any;
  subscriptions: any;
  createSubscription: any;
}

class TroubleTicketRelativeItem extends React.Component<IProps> {
  componentDidMount() {
    const { fetchSubscriptions, troubleTicket } = this.props;
    fetchSubscriptions(troubleTicket["@id"]);
  }

  updateTroubleTicketAdditionalOwners(troubleTicket: any, user: any) {
    const { updateTroubleTicket } = this.props;
    const troubleTicketObject = troubleTicketAdditionalOwnerFactory(
      troubleTicket,
      user
    );
    updateTroubleTicket(troubleTicketObject);
  }

  userAlreadyOwner(troubleTicket: any, user: any) {
    return (
      user["@id"] === troubleTicket.createdBy["@id"] ||
      Object.values(troubleTicket.additionalOwners || []).filter(
        (owner: any) => user["@id"] === owner["@id"]
      ).length > 0
    );
  }

  userAlreadySubscriber(subscriptions: any, troubleTicket: any, user: any) {
    return (
      user["@id"] === troubleTicket.createdBy["@id"] ||
      Object.values(subscriptions[troubleTicket["@id"]] || []).filter(
        (subscription: any) => user["@id"] === subscription.user["@id"]
      ).length > 0
    );
  }

  render() {
    const { troubleTicket, connectedUser, subscriptions, createSubscription } =
      this.props;

    const assignee =
      troubleTicket.assignee !== null
        ? `${troubleTicket.assignee.lastname} ${troubleTicket.assignee.firstName}`
        : "MIS";

    return (
      <div className="col-md-12">
        <div className="card ">
          <div className="card-header">
            <h3>
              <a
                href={`/en/private/mis/trouble-tickets/${troubleTicket.id}/show`}
              >
                TTS #{troubleTicket.id}
              </a>
            </h3>
          </div>
          <div className="card-body">
            <table className="table table-hover table-responsive association-table">
              <tbody>
                <tr className="back-to-line">
                  <th>{Translator.trans("tasks.assignor")}</th>
                  <td>
                    {troubleTicket.createdBy.lastname}{" "}
                    {troubleTicket.createdBy.firstname}
                  </td>
                </tr>
                <tr className="back-to-line">
                  <th>{Translator.trans("tasks.assignee")}</th>
                  <td>{assignee}</td>
                </tr>
                <tr className="back-to-line">
                  <th>{Translator.trans("fields.status")}</th>
                  <td>{troubleTicket.status}</td>
                </tr>
                <tr className="back-to-line">
                  <th>{Translator.trans("fields.short-description")}</th>
                  <td>{troubleTicket.shortDescription}</td>
                </tr>
              </tbody>
            </table>
            <div className="row justify-content-around">
              <div className="col-md-5 col-sm-12">
                <div className="btn-group" role="group">
                  <button
                    className="btn btn-warning"
                    disabled={this.userAlreadyOwner(
                      troubleTicket,
                      connectedUser
                    )}
                    onClick={() => {
                      this.updateTroubleTicketAdditionalOwners(
                        troubleTicket,
                        connectedUser["@id"]
                      );
                    }}
                  >
                    {Translator.trans("trouble_ticket.fields.same_issue")}
                  </button>
                  <button
                    className="btn"
                    style={{ backgroundColor: "#F3F3F4" }}
                  >
                    {troubleTicket.additionalOwners.length}
                  </button>
                </div>
              </div>
              <div className="col-md-5 col-sm-12">
                <div className="btn-group" role="group">
                  <button
                    className="btn btn-warning"
                    disabled={this.userAlreadySubscriber(
                      subscriptions,
                      troubleTicket,
                      connectedUser
                    )}
                    onClick={() => {
                      createSubscription(
                        troubleTicket["@id"],
                        connectedUser["@id"]
                      );
                    }}
                  >
                    {Translator.trans("trouble_ticket.fields.interested")}
                  </button>
                  <button
                    className="btn"
                    style={{ backgroundColor: "#F3F3F4" }}
                  >
                    {(subscriptions[troubleTicket["@id"]] || []).length}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

const mapStateToProps = (state: RootState) => {
  return {
    subscriptions: state.common.subscriptions,
    connectedUser: getUserDetails(state),
  };
};

const mapDispatchToProps = (dispatch: AppDispatch) => {
  return {
    createSubscription: (resource: any, user: any) =>
      dispatch(createSubscriptionAction(resource, user)),
    fetchSubscriptions: (resource: any) => dispatch(getSubscriptions(resource)),
    updateTroubleTicket: (troubleTicket: any) =>
      dispatch(
        updateTroubleTicketAction(
          troubleTicket,
          MIS_UPDATE_TROUBLE_TICKET_OWNERS
        )
      ),
  };
};

export default connect(
  mapStateToProps,
  mapDispatchToProps
)(TroubleTicketRelativeItem);

import React, { useEffect, useState } from "react";
import {
  createColumnHelper,
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table";
import { Accordion, Button, Table } from "react-bootstrap";
import moment from "moment";
import Swal from "sweetalert2";
import { DebouncedInput } from "../../utils/DebouncedInput";

interface IProps {
  troubleTicketsByModule: any;
  onTSSAddToList: any;
}

function TroubleTicketsTable({
  troubleTicketsByModule,
  onTSSAddToList,
}: IProps) {
  const handleShowAlert = (TTSId: any) => {
    Swal.fire({
      icon: "warning",
      text: 'If you press "YES", then this item will no longer appear in any specification. This action cannot be undone.',
      title: "Remove TTS from list ?",
      showCancelButton: true,
      confirmButtonColor: "#DD6B55",
      confirmButtonText: "YES",
      cancelButtonText: "NO",
    }).then((result) => {
      if (result.isConfirmed) {
        onTSSAddToList(TTSId);
      }
    });
  };
  const formatDate = (dateString: any) => {
    return moment(dateString).format("YYYY-MM-DD");
  };

  const columnHelper = createColumnHelper();

  const columns: any = [
    columnHelper.accessor("id", {
      header: "ID",
      cell: (info: any) => (
        <a href={`/en/private/mis/trouble-tickets/${info.getValue()}/show`}>
          {info.getValue()}
        </a>
      ),
      filterFn: "equalsString",
    }),
    columnHelper.accessor("status", {
      header: "Status",
      cell: (info) => info.getValue(),
      filterFn: "includesString",
    }),
    columnHelper.accessor("type.type", {
      header: "Type",
      cell: (info) => info.getValue(),
      filterFn: "includesString",
    }),
    columnHelper.accessor("createdAt ", {
      header: () => <span className="text-break">Created At</span>,
      cell: (info) => formatDate(info.getValue()),
    }),
    columnHelper.accessor(
      (row: any) => `${row.createdBy.firstname} ${row.createdBy.lastname}`,
      {
        id: "createBy",
        header: () => <span className="text-break">Created At</span>,
        cell: (info: any) => (
          <span className="text-break">{info.getValue()}</span>
        ),
        filterFn: "includesString",
      }
    ),
    columnHelper.accessor(
      (row: any) =>
        row.assignee
          ? `${row.assignee.firstname} ${row.assignee.lastname}`
          : "",
      {
        header: "Assignee",
        cell: (info: any) => (
          <span className="text-break">{info.getValue()}</span>
        ),
        filterFn: "includesString",
      }
    ),
    columnHelper.accessor("shortDescription", {
      header: "Subject",
      cell: (info) => info.getValue(),
      filterFn: "includesStringSensitive",
    }),
    columnHelper.accessor("AddToList", {
      id: "AddToList",
      header: () => "",
      cell: (info: any) => (
        <div className="d-flex justify-content-center align-items-center p-1  text-break">
          <Button
            variant="danger"
            onClick={() => handleShowAlert(info.row.getValue("id"))}
          >
            <i className="fa fa-trash me-1" /> Remove from list
          </Button>
        </div>
      ),
      enableSorting: false,
    }),
  ];

  const [data, setData] = useState(() => [...troubleTicketsByModule]);

  const [sorting, setSorting] = useState([
    {
      id: "id",
      desc: true,
    },
  ]);

  const [globalFilter, setGlobalFilter] = React.useState("");

  useEffect(() => {
    setData(troubleTicketsByModule);
  }, [troubleTicketsByModule]);

  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    onSortingChange: setSorting,
    enableSortingRemoval: false,
    state: {
      globalFilter,
      sorting,
    },
    onGlobalFilterChange: setGlobalFilter,
    getFilteredRowModel: getFilteredRowModel(), // client side filtering
  });

  return troubleTicketsByModule && troubleTicketsByModule.length > 0 ? (
    <Accordion defaultActiveKey="0">
      <Accordion.Item eventKey="0">
        <Accordion.Header className="ibox-title">
          <h5>TTS</h5>
        </Accordion.Header>
        <Accordion.Body className="ibox-content pt-0">
          <div
            className="input-group search-table  position-sticky py-3 bg-white mb-0"
            style={{ top: "0" }}
          >
            <div className="input-group-text">
              <i className="fa fa-search" />
            </div>
            <DebouncedInput
              value={globalFilter ?? ""}
              onChange={(value: any) => setGlobalFilter(value)}
              placeholder="Search in table..."
              className="form-control"
            />
          </div>

          <Table
            hover
            striped
            className="table-responsive report-table tooltip-container"
          >
            <thead
              className="position-sticky"
              style={{ backgroundColor: "#004F9E", color: "#fff", top: "70px" }}
            >
              {table.getHeaderGroups().map((headerGroup) => (
                <tr key={headerGroup.id}>
                  {headerGroup.headers.map((header: any) => {
                    return (
                      <th
                        key={header.id}
                        className="py-1 border-right border-1 py-1"
                        onClick={header.column.getToggleSortingHandler()}
