          <div className={!showSuccess ? "cell save" : "cell hidden"}>
            <button
              className="btn btn-info mx-auto text-nowrap"
              onClick={() => {
                updateEquipmentRecord(
                  equipmentRecord,
                  index,
                  equipmentRecordBeforeChanges
                );
              }}
            >
              <i className="fa fa-fw fa-save" />
              &nbsp;Save
            </button>
