const mapDispatchToProps = (dispatch: AppDispatch) => {
  return {
    hideSuccessMessage: () => dispatch(hideSuccessAlert("PART")),
    hideErrorMessage: () => dispatch(hideErrorAlert("PART")),
    writePartObject: (object: any) =>
