                    <div className="col-xs-12">
                      <FieldArray
                        name="parts"
                        component={renderPartsForm}
                        location={location}
                        module="SPR"
                      />
                      {!sph && (
                        <div className="row">
                          <div className="col-md-3">
                            <LocationSelect
                              component={renderReactVerticalSelect}
                              required
                              label="SPH"
                              name="sph"
