import { AnyAction, Reducer } from "redux";
import {
  SUCCESS,
  FAILED,
  FINANCE_FETCH_FINANCE_FAMILIES,
  FINANCE_HANDLE_FINANCE_FAMILY_FACTORIES,
  FINANCE_REMOVE_PRICING,
} from "../../constants";

export interface IFinanceFamilyState {
  financeFamilies: Array<any>;
}

let initialState: IFinanceFamilyState = {
  financeFamilies: [],
};

if (window.SF_INITIAL_STORE_STATE && window.SF_INITIAL_STORE_STATE.finance) {
  initialState = { ...initialState, ...window.SF_INITIAL_STORE_STATE.finance };
}

const financeFamilyReducer: Reducer<IFinanceFamilyState, AnyAction> = (
  // eslint-disable-next-line default-param-last
  state = initialState,
  action
) => {
  switch (action.type) {
    case FINANCE_FETCH_FINANCE_FAMILIES + SUCCESS:
      return {
        ...state,
        financeFamilies: action.payload.data["hydra:member"],
      };
    case FINANCE_FETCH_FINANCE_FAMILIES + FAILED:
      return {
        ...state,
        financeFamilies: [],
      };
    case FINANCE_HANDLE_FINANCE_FAMILY_FACTORIES:
      if (action.value === true) {
        action.financeFamily.factories.push(action.factory.value);
      } else {
        ["averagePrice", "averageMargin", "sso", "factory"].forEach((key) => {
          if (
            Object.hasOwn(
              action.financeFamily.pricings[
                `${action.sso}-${action.factory.value}`
              ],
              key
            )
          ) {
            action.financeFamily.pricings[
              `${action.sso}-${action.factory.value}`
            ][key] = "";
          }
        });
        action.financeFamily.factories = action.financeFamily.factories.filter(
          (item: any) => {
            return item !== action.factory.value;
          }
        );
      }
      state.financeFamilies[action.index] = action.financeFamily;
      return {
        ...state,
      };
    case FINANCE_REMOVE_PRICING: {
      const keys = ["averagePrice", "averageMargin", "sso", "factory"];
      keys.forEach((key) => {
        if (
          Object.hasOwn(
            action.financeFamily.pricings[`${action.sso}-${action.factory}`],
            key
          )
        ) {
          action.financeFamily.pricings[`${action.sso}-${action.factory}`][
            key
          ] = "";
        }
      });
      state.financeFamilies[action.index] = action.financeFamily;
      return {
        ...state,
      };
    }
    default:
      break;
  }
  return state;
};

export default financeFamilyReducer;

import { AnyAction, Reducer } from "redux";
import {
  SUCCESS,
  EVENT_ADD_EVENT,
  FAILED,
  HIDE_SUCCESS_ALERT,
  HIDE_ERROR_ALERT,
  EVENT_UPDATE_EVENT,
} from "../../../constants";

interface IEventReducer {
  events: Array<any>;
  showSuccess: boolean;
  showError: boolean;
  showLoading: boolean;
  errorMessage: string;
}

let initialState: IEventReducer = {
  events: [],
  showSuccess: false,
  showError: false,
  showLoading: false,
  errorMessage: "",
};

if (window.SF_INITIAL_STORE_STATE && window.SF_INITIAL_STORE_STATE.event) {
  initialState = { ...initialState, ...window.SF_INITIAL_STORE_STATE.event };
}

const eventReducer: Reducer<IEventReducer, AnyAction> = (
  // eslint-disable-next-line default-param-last
  state = initialState,
  action
) => {
  switch (action.type) {
    case EVENT_ADD_EVENT:
    case EVENT_UPDATE_EVENT:
      return {
        ...state,
        showLoading: true,
        showError: false,
        showSuccess: false,
      };
    case EVENT_ADD_EVENT + SUCCESS:
    case EVENT_UPDATE_EVENT + SUCCESS:
      return {
        ...state,
        showSuccess: true,
        showLoading: false,
        showError: false,
      };
    case EVENT_ADD_EVENT + FAILED:
    case EVENT_UPDATE_EVENT + FAILED:
      return {
        ...state,
        showError: true,
        showSuccess: false,
        showLoading: false,
        errorMessage: action.payload.data["hydra:description"] ?? "",
      };
    case `EVENT_${HIDE_SUCCESS_ALERT}`:
      return {
        ...state,
        showSuccess: false,
        showLoading: false,
        showError: false,
      };
    case `EVENT_${HIDE_ERROR_ALERT}`:
      return {
        ...state,
        showError: false,
        showLoading: false,
        showSuccess: false,
      };
    default:
      break;
  }
  return state;
};

export default eventReducer;

