export function fetchAPI(url: any, config = {}) {
  const source = axios.CancelToken.source();
  const request: any = client.get(url, {
    ...config,
    cancelToken: source.token,
  });
  request[CANCEL] = () => source.cancel();
  return request;
}

export function generateFormErrors(error: any) {
  const errors: any = {};
  if (!error.response || !error.response.data || !error.response.status) {
    errors._error = error.toString();
  } else if (
    (error.response.status === 400 || error.response.status === 422) &&
    _.has(error.response, "data.violations")
  ) {
    error.response.data.violations.forEach((violation: any) => {
      _.set(errors, violation.propertyPath, violation.message);
    });
  } else {
    errors._error =
      error.response.data["hydra:description"] ||
      error.response.data.message ||
      "Internal Server Error.";
  }

  return errors;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const handleApiError = <P>(error: any) => {
  const response: IBasicApiResponse<P> = {};
  if (error?.status) {
    response.status = error.status;
  }
  if (error?.stage) {
    response.status = 404;
  }
  response.error = error;
  if (error?.status !== 500 && error?.response?.data?.detail) {
    response.errorMessage = error.response.data.detail;
  } else {
    response.errorMessage = Translator.trans("common.error.server");
  }
  return response;
};

export class ValidationError extends Error {
  violations: any;

  constructor(violations = [], ...args: Array<any>) {
    super(...args);

    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, ValidationError);
    }

    this.violations = violations;
  }
}

export function nl2br(str: any, isXhtml: any) {
  const breakTag =
    isXhtml || typeof isXhtml === "undefined" ? "<br />" : "<br>";
  return `${str}`.replace(/([^>\r\n]?)(\r\n|\n\r|\r|\n)/g, `$1${breakTag}$2`);
}
export function entityToChar(str: any) {
  const textarea = document.createElement("textarea");
  textarea.innerHTML = str;
  return textarea.value;
}

export function isValidDate(date: any) {
  return (
    date &&
    Object.prototype.toString.call(date) === "[object Date]" &&
    !Number.isNaN(date)
  );
}

export function formatDate(date: any) {
  /* Format: yyyy-mm-dd */
  return isValidDate(date)
    ? `${date.getFullYear()}-${`0${date.getMonth() + 1}`.slice(
        -2
      )}-${`0${date.getDate()}`.slice(-2)}`
    : null;
}

export function removeTags(str: any) {
  if (!str) return "";

  str = str.replace(/<\/?(p|ul|li|h1|h2|h3|h4|h5|h6|div|br)>/gi, " ");

  str = str.replace(/(<([^>]+)>)/gi, "");

  str = str.replace(/&nbsp;/gi, " ");

  return str.trim().replace(/\s+/g, " ");
}

export function shortenString(string: any, maxSize = 20) {
  if (!string) return "";

  const strippedString = removeTags(string);

  return strippedString.length > maxSize
    ? `${strippedString.substring(0, maxSize - 1)}...`
    : strippedString;
}

