export const extractDigits = (input: string) => {
  return input.replace(/\D/g, "");
};

export const extractFloat = (input: string): string => {
  let foundDecimal = false;
  return input
    .split("")
    .filter((char) => {
      if (/\d/.test(char)) return true;
      if (char === "." && !foundDecimal) {
        foundDecimal = true;
        return true;
      }
      return false;
    })
    .join("");
};

